-- Payroll-cycle file review 2026-10-07: activate 41 inactive sites; extend their expired contracts to 1 Dec 2026.
BEGIN;
UPDATE public.units SET status='active', updated_at=now() WHERE code IN ('CLI4225','CLI4226','CLI4227','CLI4304','CLI4306','CLI4308','CLI4309','CLI4314','CLI4316','CLI4318','CLI4319','CLI4324','CLI4325','CLI4329','CLI4334','CLI4352','CLI4224','CLI4347','CLI4337','CLI4343','CLI4353','CLI4354','CLI4355','CLI4356','CLI4357','CLI4359','CLI4360','CLI4361','CLI4362','CLI4363','CLI4364','CLI4365','CLI4366','CLI4367','CLI4368','CLI4369','CLI4370','CLI4371','CLI4372','CLI4339','CLI4342') AND status IS DISTINCT FROM 'active';
UPDATE public.client_contracts cc SET end_date='2026-12-01',
  expiry_date=CASE WHEN cc.expiry_date IS NOT NULL THEN '2026-12-01'::date END, status='active', updated_at=now()
FROM public.units u WHERE u.id=cc.unit_id AND u.code IN ('CLI4225','CLI4226','CLI4227','CLI4304','CLI4306','CLI4308','CLI4309','CLI4314','CLI4316','CLI4318','CLI4319','CLI4324','CLI4325','CLI4329','CLI4334','CLI4352','CLI4224','CLI4347','CLI4337','CLI4343','CLI4353','CLI4354','CLI4355','CLI4356','CLI4357','CLI4359','CLI4360','CLI4361','CLI4362','CLI4363','CLI4364','CLI4365','CLI4366','CLI4367','CLI4368','CLI4369','CLI4370','CLI4371','CLI4372','CLI4339','CLI4342') AND coalesce(cc.end_date,cc.expiry_date) < current_date;
COMMIT;
